<?php
require __DIR__.'/lib.php';if(logged()){header('Location: index.php');exit;}
$err='';$name='';$username='';$ready=false;
try{$ready=registration_ready();}catch(Throwable $e){$err='Sign Up is temporarily unavailable. Please contact the administrator.';}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $name=trim($_POST['name']??'');$username=trim($_POST['username']??'');
 try{verify_csrf();register_user_request($name,$username,$_POST['password']??'',$_POST['confirm_password']??'');$_SESSION['signup_success']=true;header('Location: signup.php');exit;}
 catch(Throwable $e){$err=$e instanceof PDOException?'Unable to submit the registration. Please try again later.':$e->getMessage();}
}
$success=!empty($_SESSION['signup_success']);unset($_SESSION['signup_success']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign Up | E-commerce Inventory Management System</title><link rel="icon" href="assets/logos/rs8.png"><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="assets/typography.css?v=5.4.6-b"></head><body class="auth-bg"><div class="auth-card"><img class="auth-logo" src="assets/logos/rs8.png" alt="RS8"><h1>Create Account</h1><p class="muted">E-commerce Inventory Management System</p><?php if($success):?><div class="alert success"><b>Registration submitted.</b><br>Your account is Pending Approval. An administrator must approve it before you can sign in.</div><a class="btn primary block" href="login.php">Back to Login</a><?php else:?><?php if($err):?><div class="alert danger"><?=e($err)?></div><?php endif;?><?php if(!$ready):?><div class="alert warn">Sign Up is not available yet. Ask the administrator to complete the system upgrade.</div><?php else:?><div class="alert info">New accounts require Admin approval. Your access role will be assigned by the administrator.</div><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Full Name<input name="name" value="<?=e($name)?>" maxlength="120" autocomplete="name" required></label><label>Username<input name="username" value="<?=e($username)?>" minlength="3" maxlength="80" pattern="[A-Za-z0-9][A-Za-z0-9._\-]{2,79}" autocomplete="username" required></label><label>Password<input type="password" name="password" minlength="8" maxlength="72" autocomplete="new-password" required></label><label>Confirm Password<input type="password" name="confirm_password" minlength="8" maxlength="72" autocomplete="new-password" required></label><button class="btn primary block">Submit Registration</button></form><?php endif;?><p class="small muted">Already registered? <a class="auth-link" href="login.php">Back to Login</a></p><?php endif;?></div><script src="assets/app.js"></script></body></html>
